    default boolean filterMemberLeftClan()
    {
        return false;
    }

    @ConfigItem(
            keyName = "filterQuestComplete",
            name = "Filter Quest Completions",
            description = "Remove quest completion broadcasts from clan chat",
            section = filterSectionGeneral,
            position = 7
