        when(config.collectionLogThreshold()).thenReturn(1000);
        when(config.filterCollectionLogBosses()).thenReturn(true);

        assertHidden(collectionLog("Abyssal whip", 1200));
        assertShown(collectionLog("Fighter hat", 1200));
    }
}

